<div class="row g-3">
  <div class="col-lg-6">
    <div class="card-panel mb-3"><div class="panel-head"><div><h3>Backups</h3><p>Tenant-scoped compressed JSON backup.</p></div><button class="btn btn-primary ajax-action" data-url="<?= url('/tools/backup') ?>">Run Backup</button></div><?php foreach($backups as $b): ?><div class="report-row"><span><?= e($b['backup_type'].' · '.$b['created_at']) ?><small><?= e($b['file_path']??$b['message']??'') ?></small></span><span class="status-badge <?= $b['status']==='success'?'success':($b['status']==='failed'?'danger':'') ?>"><?= e($b['status']) ?></span></div><?php endforeach; ?></div>
    <div class="card-panel mb-3"><h3 class="h6">API Tokens</h3><form class="ajax-form row g-2 mb-3" method="post" action="<?= url('/tools/api-tokens') ?>"><?= csrf_field() ?><div class="col-md-4"><input class="form-control" name="name" placeholder="Token name"></div><div class="col-md-5"><select class="form-select" name="user_id"><?php foreach($users as $u): ?><option value="<?= $u['id'] ?>"><?= e($u['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><button class="btn btn-primary w-100">Generate</button></div></form><?php foreach($tokens as $t): ?><div class="report-row"><span><?= e($t['name']) ?><small><?= e($t['user_name'].' · '.($t['last_used_at']??'never used')) ?></small></span><span class="status-badge"><?= $t['revoked_at']?'revoked':'active' ?></span></div><?php endforeach; ?></div>
    <div class="card-panel"><h3 class="h6">Tags</h3><form class="ajax-form d-flex gap-2 mb-3" method="post" action="<?= url('/tools/tags') ?>"><?= csrf_field() ?><input class="form-control" name="name" placeholder="VIP, Contract, Hotel..." required><button class="btn btn-outline-primary">Add</button></form><div class="d-flex gap-2 flex-wrap"><?php foreach($tags as $tag): ?><span class="status-badge"><?= e($tag['name']) ?></span><?php endforeach; ?></div></div>
